package io.github.toolazytoname.xiaohei;
public final class RootAuditRevocationTest {public static void main(String[] x){RootCapabilityBroker b=new RootCapabilityBroker();RootCapabilityBroker.Request ok=new RootCapabilityBroker.Request("root-request-audit-0001","xiaohei-root-broker-v1",RootCapabilityBroker.Action.READ_AUDIO_STATUS,"{}");if(b.authorize(ok).decision!=RootCapabilityBroker.Decision.ALLOW_ONCE)throw new AssertionError();if(b.auditSnapshot().size()!=1||!"read_audio_status".equals(b.auditSnapshot().get(0).action))throw new AssertionError();b.revokeAll();if(!b.revoked())throw new AssertionError();RootCapabilityBroker.Request later=new RootCapabilityBroker.Request("root-request-audit-0002","xiaohei-root-broker-v1",RootCapabilityBroker.Action.READ_BATTERY_STATUS,"{}");if(b.authorize(later).decision!=RootCapabilityBroker.Decision.DENY_REVOKED)throw new AssertionError();if(b.auditSnapshot().size()!=2||b.auditSnapshot().get(1).decision!=RootCapabilityBroker.Decision.DENY_REVOKED)throw new AssertionError();try{b.auditSnapshot().clear();throw new AssertionError();}catch(UnsupportedOperationException expected){}System.out.println("PASS RootAuditRevocationTest audit=2 fields=3 request_data=0 revoke=permanent post_revoke=deny execution_paths=0");}}
